from pathlib import Path
from zipfile import ZipFile,ZIP_DEFLATED
import json,hashlib,subprocess
w=Path('work').resolve();p=w/'hekate-nova-pro-v34-alpha5';o=w.parent/'outputs';sha=lambda b:hashlib.sha256(b).hexdigest()
for n in ('nova34a5-tv-sync-check.json','nova34a5-tv-integration.json','nova34a5-header-check.json','nova34a5-copy-check.json','nova34a5-partition-check.json','nova34a5-fatfs-check.json'):assert json.loads((w/n).read_text())['passed']
assert 'PASS' in json.loads((w/'nova34a5-tv-lifecycle-check.json').read_text())['result']
note='''Hekate Nova Pro v34 alpha 5 — maintien de la sortie TV\n\nLe mode TV est maintenant servi pendant les opérations synchrones : partitionnement SD, copie/vérification emuMMC, sauvegarde/restauration et attentes de confirmation par boutons. L’image complète est transmise après le rafraîchissement de l’interface ; les boucles longues font avancer le service dock sans relancer tout le planificateur graphique.\n\nLes rapports TV sont différés pendant ces boucles : aucun montage, démontage ou fichier de journal TV n’est écrit en concurrence avec le partitionnement ou la copie. Les journaux en attente sont traités au retour dans la boucle normale de Nyx.\n\nUtilisation : activer Démarrage TV/détection automatique dans Réglages Nyx, ou démarrer la TV manuellement avant l’opération ; placer la console directement dans le dock officiel alimenté et relié en HDMI. Le choix de conserver l’écran console reste respecté. Après un échec de négociation ou de lien vidéo, jusqu’à trois tentatives au total sont possibles, espacées de 1,5 puis 3 secondes après nettoyage. Aucun reset forcé du contrôleur PD ; arrêt manuel, défaut matériel signalé ou transfert de contrôle annulent les relances. Les arrêts de sécurité au retrait du dock, les transferts de contrôle USB/payload/OS et l’isolation des diagnostics matériels restent conservés. Un changement de payload, un redémarrage ou une TV débranchée n’assurent pas un affichage continu.\n\nInstaller le dossier bootloader et utiliser le payload de ce pack. Les réglages personnels sont conservés. Le payload est aussi livré dans bootloader/payloads pour apparaître dans la liste. Le pack 8GB reste réservé aux consoles physiquement modifiées.\n\nValidation PC : 54 scénarios du service TV dont rafraîchissement manuel, fermeture de la fenêtre, dock retiré, rapports différés sans accès SD, fin de négociation, VOL−, remise en route normale et débordement du compteur temps ; fonctions réelles de maintenance/présentation/attente de boutons testées ; 3664 assertions de transaction/tables, 246 de copie/activation et 147 avec FatFs réel sur FAT32/exFAT virtuels. Compilation ARM et en-têtes binaires vérifiés. Aucun test d’affichage HDMI ou de partitionnement sur Switch effectué ici : essai sur OLED/dock officiel à effectuer sur une carte sauvegardée.\n'''
note+='\nRapports utilisateur tests 12/13 : échec d’identification du dock dans un cas ; lien entraîné mais flux vidéo non synchronisé dans l’autre. Nova attend maintenant jusqu’à une seconde une confirmation fraîche du récepteur après démarrage du flux ; absence de synchronisation, erreur AUX ou retrait HPD ne sont plus annoncés comme une configuration réussie. Ces échecs passent par le nettoyage et les tentatives limitées. Neuf scénarios supplémentaires de synchronisation sont vérifiés sur PC. Le numéro du journal TV reflète désormais la version Nova réelle. Ce correctif reste à confirmer sur la TV concernée.\n'
(o/'LIRE-MOI-NOVA34-ALPHA5.txt').write_text(note,encoding='utf-8');(p/'ASSISTANT-V34-ALPHA5.txt').write_text(note,encoding='utf-8')
translations={'fr':'Maintien du service TV pendant les opérations longues, rafraîchissement après chaque image terminée, journaux TV différés pour éviter tout accès SD réentrant. Attentes de boutons coopératives. Réglages et arrêts matériels conservés. Validation matérielle à effectuer.','en':'Keep TV serviced during long operations, present completed frames, defer TV logs to avoid reentrant SD access, and service physical-button waits. Preserve settings and hardware shutdown guards. Physical validation pending.','es':'Servicio TV durante operaciones largas y esperas de botones. Presentación de imágenes completas y registros diferidos sin acceso SD simultáneo. Ajustes y protecciones conservados. Falta validación física.','it':'Servizio TV durante operazioni lunghe e attese dei pulsanti. Immagini complete e registri differiti senza accesso SD rientrante. Impostazioni e protezioni mantenute. Verifica hardware da eseguire.','de':'TV-Dienst während langer Vorgänge und Tastenwartezeiten. Fertige Bilder übertragen, Protokolle ohne rekursiven SD-Zugriff verzögern. Einstellungen und Schutzabschaltungen bleiben erhalten. Hardwareprüfung ausstehend.','pt':'Serviço TV durante operações longas e esperas de botões. Imagens completas e registos adiados sem acesso SD recursivo. Definições e proteções mantidas. Validação física pendente.','ru':'Обслуживание TV во время длительных операций и ожидания кнопок. Передача готовых кадров и отложенная запись журналов без повторного доступа к SD. Настройки и защитные отключения сохранены. Проверка на консоли ожидается.','zh-CN':'长时间操作和等待按键时保持 TV 服务，完成画面后更新输出，延迟保存日志以避免重复访问 SD。保留设置和硬件保护，仍需实机验证。'}
for key,value in {'fr': ' Jusqu’à trois tentatives espacées après échec de connexion ; aucun reset PD forcé et arrêt manuel prioritaire.', 'en': ' Up to three spaced attempts after connection failure; no forced PD reset and manual stop takes priority.', 'es': ' Hasta tres intentos espaciados tras fallo; sin reinicio PD forzado y parada manual prioritaria.', 'it': ' Fino a tre tentativi distanziati dopo un errore; nessun reset PD forzato e arresto manuale prioritario.', 'de': ' Bis zu drei zeitversetzte Versuche nach Verbindungsfehler; kein erzwungener PD-Reset, manueller Stopp hat Vorrang.', 'pt': ' Até três tentativas espaçadas após falha; sem reset PD forçado e paragem manual prioritária.', 'ru': ' До трёх попыток с паузами после ошибки связи; без принудительного сброса PD, ручная остановка имеет приоритет.', 'zh-CN': ' 连接失败后最多间隔重试三次，不强制重置 PD，手动停止优先。'}.items():translations[key]+=value
for key,value in {'fr':' Confirmation fraîche de synchronisation vidéo (attente bornée à 1 s) ; échec explicite sans synchronisation/AUX/HPD. Numéro de journal corrigé.', 'en':' Require fresh video stream sync within 1 s; fail explicitly on missing sync/AUX/HPD. Correct log version.', 'es':' Confirmación nueva de sincronización en 1 s; error explícito sin sincronización/AUX/HPD. Versión del registro corregida.', 'it':' Conferma aggiornata della sincronizzazione entro 1 s; errore esplicito senza sincronizzazione/AUX/HPD. Versione registro corretta.', 'de':' Frische Videosynchronisation innerhalb 1 s erforderlich; Fehler bei fehlendem Sync/AUX/HPD. Protokollversion korrigiert.', 'pt':' Confirmação atual da sincronização em 1 s; erro explícito sem sincronização/AUX/HPD. Versão do registo corrigida.', 'ru':' Требуется свежее подтверждение синхронизации за 1 с; явная ошибка при отсутствии синхронизации/AUX/HPD. Версия журнала исправлена.', 'zh-CN':' 最多等待 1 秒获取最新视频同步确认；同步、AUX 或 HPD 失败时明确报错，修正日志版本。'}.items():translations[key]+=value
reports=['nova34a5-tv-sync-check.json','nova34a5-tv-lifecycle-check.json','nova34a5-tv-integration.json','nova34a5-header-check.json','nova34a5-copy-check.json','nova34a5-partition-check.json','nova34a5-fatfs-check.json']
summary={}
for suffix in ('','-8GB'):
 with ZipFile(o/('hekate-nova-pro-v34-alpha4'+suffix+'.zip'))as z:files={n:z.read(n)for n in z.namelist()if not n.endswith('/')and not n.startswith('hekate_nova_pro_')and n not in ('BUILD-INFO.json','BUNDLE-MANIFEST.json')}
 for n in ('nyx.bin','libsys_lp0.bso','libsys_minerva.bso'):files['bootloader/sys/'+n]=(p/'output'/n).read_bytes()
 payload=bytearray((p/'output/hekate.bin').read_bytes());assert not payload[0x122]&1
 if suffix:payload[0x122]|=1
 name='hekate_nova_pro_6.5.5_v34_alpha5'+('_8GB_EXPERIMENTAL'if suffix else'')+'.bin';files[name]=files['bootloader/update.bin']=files['bootloader/payloads/'+name]=bytes(payload)
 files['LIRE-MOI.txt']=note.encode();files['documentation/TV-V34-ALPHA5.txt']=note.encode()
 for code,t in translations.items():files['documentation/changelogs/CHANGELOG-NOVA34-ALPHA5-'+code+'.md']=('# Hekate Nova Pro v34 alpha 5\n\n'+t+'\n').encode()
 for n in reports:files['verification/'+n]=(w/n).read_bytes()
 files['BUILD-INFO.json']=json.dumps({'version':'34-alpha5','variant':'8GB-experimental'if suffix else'standard','compiled':True,'physical_console_test':False,'tv_long_operations':True},indent=2).encode()
 files['BUNDLE-MANIFEST.json']=json.dumps({n:sha(b)for n,b in files.items()},indent=2).encode()
 target=o/('hekate-nova-pro-v34-alpha5'+suffix+'.zip');assert not target.exists()
 with ZipFile(target,'w',ZIP_DEFLATED,compresslevel=6)as z:
  for n,b in sorted(files.items()):z.writestr(n,b)
 with ZipFile(target)as z:assert z.testzip()is None
 summary[target.name]={'bytes':target.stat().st_size,'sha256':sha(target.read_bytes())}
# Complete source and unchanged standalone diagnostic dependencies.
with ZipFile(o/'hekate-nova-pro-v34-alpha4-sources.zip')as z:files={n:z.read(n)for n in z.namelist()if not n.endswith('/')and not n.startswith('hekate-nova-pro-v34-alpha4/')}
for f in p.rglob('*'):
 if f.is_file()and not any(x in ('build','output','.git','__pycache__')for x in f.relative_to(p).parts)and f.name not in ('payload_00.h','payload_01.h'):files['hekate-nova-pro-v34-alpha5/'+f.relative_to(p).as_posix()]=f.read_bytes()
for f in w.glob('*nova34a5*.py'):files['build-tools/'+f.name]=f.read_bytes()
for f in (w/'nova34a5-tv-tests').rglob('*'):
 if f.is_file()and f.suffix not in ('.exe',):files['build-tools/nova34a5-tv-tests/'+f.relative_to(w/'nova34a5-tv-tests').as_posix()]=f.read_bytes()
for n in reports:files['verification/'+n]=(w/n).read_bytes()
target=o/'hekate-nova-pro-v34-alpha5-sources.zip'
with ZipFile(target,'w',ZIP_DEFLATED,compresslevel=6)as z:
 for n,b in files.items():z.writestr(n,b)
summary[target.name]={'bytes':target.stat().st_size,'sha256':sha(target.read_bytes())}
(w/'nova34a5-package-check.json').write_text(json.dumps({'passed':True,'archives':summary,'hardware_validated':False},indent=2))
(o/'hekate-nova-pro-v34-alpha5-SHA256.txt').write_text(''.join(v['sha256']+'  '+k+'\n'for k,v in summary.items()))
print(json.dumps(summary,indent=2))
